const covered = new Set(
  analysis.verdicts.map((v) => v.beer_id).filter((id) => byId.has(id)),
).size;
if (covered === 0) {
  log.error({ batch: orphans.length, stopReasons: exchanges.map((e) => e.raw.stopReason) },
    'orphan-triage: zero verdicts after retry');
  finish({ ...outcome, error: `LLM повернув 0 вердиктів (${exchanges.length} спроб)` });
  return;
}
if (covered < orphans.length) {
  // guardHits is why, not just how many. Three of the four #408 guards end in
  // `skipped`, and a skipped row keeps review_class NULL and comes back tomorrow —
  // so a model that keeps making the same illegal proposal would recirculate the
  // same rows forever while the batch silently filled with repeat offenders. One
  // line has to make that visible instead of leaving it to be inferred from a
  // backlog that stopped moving.
  log.warn({ covered, batch: orphans.length, guardHits: plan.guardHits },
    'orphan-triage: verdict shortfall');
}

for (const v of plan.quiet) {
  review(v, null);
  if (v.review_class === 'not_on_untappd') outcome.notOnUntappd++;
  else outcome.wontfix++;
}

if (hasIssue) {
  const target = byNumber.get(verdict.issue_number!);
  if (!target) { skipped++; continue; }
  // Guard 4: a saturated issue stops accepting rows. #347 took 36 rows across 18
  // comment batches in 19 days and shipped nothing — the pile itself was the
  // signal, and nothing was watching it.
  if (target.postCreationRows >= MAX_ROWS_PER_ISSUE) {
    guardHits.saturated += 1;
    skipped++;
    continue;
  }
  // Guard 2: the row must not contradict what the issue claims to be about. An
  // unscoped issue (no `triage-scope` block in its body) accepts nothing — that is
  // what makes the one-time backfill of existing issues load-bearing rather than
  // cosmetic. We deliberately do NOT re-route on failure: choosing a different
  // issue is exactly the title-similarity judgement that produced the pile.
  if (target.scope === null || !rowSatisfiesScope(row, verdict.review_class, target.scope)) {
    guardHits.scope_violation += 1;
    skipped++;
    continue;
  }
  pushInto(byIssue, verdict.issue_number!, verdict);
} else {
  if (!allowedKeys.has(verdict.new_issue_key!)) { skipped++; continue; }
  pushInto(byKey, verdict.new_issue_key!, verdict);
}

